export const LOCKER_SOURCE = "// Token locker: lock, cliff, stream, claim, cancel.\n//\n// A sender locks tokens for a recipient. Nothing unlocks before the cliff.\n// From the cliff on, an equal part unlocks every period, and the recipient\n// claims whenever they like: unlocked tokens wait in the locker until then.\n// If the lock was created as cancelable, the sender can cancel before any\n// period: what has not unlocked goes back to the sender, and everything that\n// has unlocked still goes to the recipient. A lock that is not cancelable\n// cannot be cancelled by anyone.\n//\n// Tokens are linear, so on every path the sender's share and the recipient's\n// share add up to exactly what was locked. Nothing can stay in the locker.\n\nrecord Token mode linear {\n  amount : U64\n}\n\ncallable Carve(pot : Token, part : U64) -> (Token, Token) {\n  requires part <= pot.amount;\n  outcomes { success (Token, Token) };\n}\n\nfn carve(pot : Token, part : U64) -> (Token, Token) satisfies Carve {\n  let Token { amount = total } = pot;\n  return (construct Token { amount = part }, construct Token { amount = total - part });\n}\n\ncallable Stack(a : Token, b : Token) -> Token {\n  outcomes { success Token };\n}\n\nfn stack(a : Token, b : Token) -> Token satisfies Stack {\n  let Token { amount = x } = a;\n  let Token { amount = y } = b;\n  return construct Token { amount = x + y };\n}\n\n// How much of the lock has unlocked once `period` periods have passed.\n// Nothing before the cliff; everything at the end, so rounding strands nothing.\ncallable Unlocked(total : U64, periods : U64, cliff : U64, period : U64) -> U64 {\n  requires periods > 0;\n  requires period <= periods;\n  requires total <= 1000000000000;\n  outcomes { success U64 };\n}\n\nfn unlocked(total : U64, periods : U64, cliff : U64, period : U64) -> U64 satisfies Unlocked {\n  if lt(period, cliff) {\n    return 0;\n  } else {\n    if eq(period, periods) {\n      return total;\n    } else {\n      return total / periods * period;\n    };\n  };\n}\n\n// Sender and locker. Before every period the sender keeps the lock or asks to cancel.\nprotocol Lock {\n  role Sender = send (deposit : Token) then recursive Period = offer {\n    Due => select {\n      Keep => continue Period |\n      Cancel => offer {\n        Cancelled => receive (unvested : Token) then end Cancelled |\n        Refused => continue Period\n      }\n    } |\n    Complete => end Complete\n  };\n  role Locker = receive (deposit : Token) then recursive Period = select {\n    Due => offer {\n      Keep => continue Period |\n      Cancel => select {\n        Cancelled => send (unvested : Token) then end Cancelled |\n        Refused => continue Period\n      }\n    } |\n    Complete => end Complete\n  };\n}\n\n// Locker and recipient. Each period the locker says what can be claimed; the recipient takes it or waits.\nprotocol Claim {\n  role Locker = recursive Period = select {\n    Open => send (claimable : U64) then offer {\n      Withdraw => send (tokens : Token) then continue Period |\n      Wait => continue Period\n    } |\n    Closed => send (rest : Token) then end Closed\n  };\n  role Recipient = recursive Period = offer {\n    Open => receive (claimable : U64) then select {\n      Withdraw => receive (tokens : Token) then continue Period |\n      Wait => continue Period\n    } |\n    Closed => receive (rest : Token) then end Closed\n  };\n}\n\ncomponent Sender(locker : Sender[Lock], total : {v : U64 | v <= 1000000000000}, cancel_at : U64) provides Token {\n  let locked = send construct Token { amount = total } on locker;\n  let back = loop state (ep = locked, period : U64 = 1) {\n    offer ep {\n      Due => {\n        if eq(period, cancel_at) {\n          let asking = select Cancel on ep;\n          offer asking {\n            Cancelled => {\n              let (done, unvested) = receive Token on asking;\n              close done;\n              console_write(\"sender cancelled before period\", period);\n              break (unvested);\n            }\n            Refused => {\n              console_write(\"cancel refused: this lock is not cancelable\");\n              continue (asking, period + 1);\n            }\n          };\n        } else {\n          let keeping = select Keep on ep;\n          continue (keeping, period + 1);\n        };\n      }\n      Complete => {\n        close ep;\n        break (construct Token { amount = 0 });\n      }\n    };\n  };\n  let returned = borrow back as b { return b.amount; };\n  console_write(\"sender got back\", returned);\n  return back;\n}\n\ncomponent Locker(\n  sender : Locker[Lock],\n  recipient : Locker[Claim],\n  periods : {v : U64 | v > 0},\n  cliff : U64,\n  cancelable : Bool\n) {\n  let (s1, deposit) = receive Token on sender;\n  let total = borrow deposit as d { return d.amount; };\n  loop state (s = s1, r = recipient, pot = deposit, period : U64 = 1, claimed : U64 = 0) {\n    if gt(period, periods) {\n      // Finished: whatever is unlocked and unclaimed goes to the recipient.\n      let s_done = select Complete on s;\n      close s_done;\n      let closing = select Closed on r;\n      let r_done = send pot on closing;\n      close r_done;\n      break;\n    } else {\n      let asked = select Due on s;\n      offer asked {\n        Keep => {\n          let open = unlocked(total, periods, cliff, period) - claimed;\n          let r1 = select Open on r;\n          let r2 = send open on r1;\n          offer r2 {\n            Withdraw => {\n              let (out, rest) = carve(pot, open);\n              let r3 = send out on r2;\n              continue (asked, r3, rest, period + 1, claimed + open);\n            }\n            Wait => {\n              continue (asked, r2, pot, period + 1, claimed);\n            }\n          };\n        }\n        Cancel => {\n          if cancelable {\n            // Split what is left: unlocked-but-unclaimed to the recipient, the rest back to the sender.\n            let owed = unlocked(total, periods, cliff, period - 1) - claimed;\n            let (for_recipient, for_sender) = carve(pot, owed);\n            let cancelled = select Cancelled on asked;\n            let s_done = send for_sender on cancelled;\n            close s_done;\n            let closing = select Closed on r;\n            let r_done = send for_recipient on closing;\n            close r_done;\n            break;\n          } else {\n            let refused = select Refused on asked;\n            let open = unlocked(total, periods, cliff, period) - claimed;\n            let r1 = select Open on r;\n            let r2 = send open on r1;\n            offer r2 {\n              Withdraw => {\n                let (out, rest) = carve(pot, open);\n                let r3 = send out on r2;\n                continue (refused, r3, rest, period + 1, claimed + open);\n              }\n              Wait => {\n                continue (refused, r2, pot, period + 1, claimed);\n              }\n            };\n          };\n        }\n      };\n    };\n  };\n}\n\ncomponent Recipient(locker : Recipient[Claim], claim_every : {v : U64 | v > 0}) provides Token {\n  let held = loop state (ep = locker, mine = construct Token { amount = 0 }, period : U64 = 1) {\n    offer ep {\n      Open => {\n        let (e1, claimable) = receive U64 on ep;\n        if eq(period / claim_every * claim_every, period) {\n          if gt(claimable, 0) {\n            let taking = select Withdraw on e1;\n            let (e2, tokens) = receive Token on taking;\n            console_write(\"period\", period, \"recipient claims\", claimable);\n            continue (e2, stack(mine, tokens), period + 1);\n          } else {\n            let waiting = select Wait on e1;\n            continue (waiting, mine, period + 1);\n          };\n        } else {\n          let waiting = select Wait on e1;\n          continue (waiting, mine, period + 1);\n        };\n      }\n      Closed => {\n        let (done, rest) = receive Token on ep;\n        close done;\n        break (stack(mine, rest));\n      }\n    };\n  };\n  let amount = borrow held as h { return h.amount; };\n  console_write(\"recipient holds\", amount);\n  return held;\n}\n\narchitecture TokenLocker {\n  instance sender = Sender;\n  instance locker = Locker;\n  instance recipient = Recipient;\n  process sender_run = sender;\n  process locker_run = locker;\n  process recipient_run = recipient;\n  protocol lock = Lock;\n  protocol payout = Claim;\n  role lock.Sender = sender;\n  role lock.Locker = locker;\n  role payout.Locker = locker;\n  role payout.Recipient = recipient;\n  entry total : U64;\n  entry periods : U64;\n  entry cliff : U64;\n  entry cancelable : Bool;\n  entry cancel_at : U64;\n  entry claim_every : U64;\n  bind sender.locker = lock.Sender;\n  bind sender.total = total;\n  bind sender.cancel_at = cancel_at;\n  bind locker.sender = lock.Locker;\n  bind locker.recipient = payout.Locker;\n  bind locker.periods = periods;\n  bind locker.cliff = cliff;\n  bind locker.cancelable = cancelable;\n  bind recipient.locker = payout.Recipient;\n  bind recipient.claim_every = claim_every;\n}\n\nprogram main = instantiate TokenLocker;\n";
export const HOOKS_SOURCE = "// Transfer hooks: programs that run on every transfer of a token.\n//\n// A sender asks the token program to move tokens to a receiver. Before anything\n// moves, the token program runs its hooks in order:\n//\n//   1. a limit hook, which only looks at the amount and allows or blocks it;\n//   2. a fee hook, which is handed the tokens, keeps a cut, and hands the rest back.\n//\n// A blocked transfer returns everything to the sender. Tokens are linear, so a\n// hook that is handed tokens has to pass every one of them on or keep it as its\n// stated fee: it cannot lose any. The token program then checks, in writing,\n// that the hook did not keep more than the cap.\n\nrecord Token mode linear {\n  amount : U64\n}\n\ncallable Carve(pot : Token, part : U64) -> (Token, Token) {\n  requires part <= pot.amount;\n  outcomes { success (Token, Token) };\n}\n\nfn carve(pot : Token, part : U64) -> (Token, Token) satisfies Carve {\n  let Token { amount = total } = pot;\n  return (construct Token { amount = part }, construct Token { amount = total - part });\n}\n\n// A hook may keep at most 5% of what it was handed. The token program checks\n// what comes back against what it sent, so it does not have to trust the hook.\ncallable Accept(returned : Token, sent : U64) -> Token {\n  requires sent <= 1000000000000;\n  requires returned.amount <= sent;\n  requires returned.amount * 100 >= sent * 95;\n  outcomes { success Token };\n}\n\nfn approve(returned : Token, sent : U64) -> Token satisfies Accept {\n  return returned;\n}\n\n// Sender and token program.\nprotocol Transfer {\n  role Sender = send (tokens : Token) then offer {\n    Sent => end Sent |\n    Blocked => receive (tokens : Token) then end Blocked\n  };\n  role Program = receive (tokens : Token) then select {\n    Sent => end Sent |\n    Blocked => send (tokens : Token) then end Blocked\n  };\n}\n\n// A hook that only inspects the transfer.\nprotocol Inspect {\n  role Program = send (amount : U64) then offer {\n    Allow => end Allowed |\n    Deny => end Denied\n  };\n  role Hook = receive (amount : U64) then select {\n    Allow => end Allowed |\n    Deny => end Denied\n  };\n}\n\n// A hook that is handed the tokens and must hand them back, less its fee.\n// If the transfer was blocked earlier, it is told to stand down.\nprotocol Custody {\n  role Program = select {\n    Run => send (tokens : Token) then receive (rest : Token) then end Done |\n    Skip => end Skipped\n  };\n  role Hook = offer {\n    Run => receive (tokens : Token) then send (rest : Token) then end Done |\n    Skip => end Skipped\n  };\n}\n\n// Token program and receiver.\nprotocol Deliver {\n  role Program = select {\n    Arrived => send (tokens : Token) then end Arrived |\n    Nothing => end Nothing\n  };\n  role Receiver = offer {\n    Arrived => receive (tokens : Token) then end Arrived |\n    Nothing => end Nothing\n  };\n}\n\ncomponent Sender(ledger : Sender[Transfer], amount : {v : U64 | v <= 1000000000000}) provides U64 {\n  let asked = send construct Token { amount = amount } on ledger;\n  offer asked {\n    Sent => {\n      close asked;\n      console_write(\"sender: transfer went through\");\n      return 0;\n    }\n    Blocked => {\n      let (done, tokens) = receive Token on asked;\n      close done;\n      let Token { amount = back } = tokens;\n      console_write(\"sender: transfer blocked, tokens returned:\", back);\n      return back;\n    }\n  };\n}\n\ncomponent LimitHook(ledger : Hook[Inspect], max_transfer : U64) {\n  let (deciding, amount) = receive U64 on ledger;\n  if le(amount, max_transfer) {\n    let allowed = select Allow on deciding;\n    close allowed;\n  } else {\n    let denied = select Deny on deciding;\n    close denied;\n    console_write(\"limit hook: over the limit of\", max_transfer);\n  };\n}\n\ncomponent FeeHook(ledger : Hook[Custody], fee_bps : {v : U64 | v <= 500}) provides U64 {\n  offer ledger {\n    Run => {\n      let (returning, tokens) = receive Token on ledger;\n      let held = borrow tokens as t { return t.amount; };\n      let (fee, rest) = carve(tokens, held * fee_bps / 10000);\n      let done = send rest on returning;\n      close done;\n      let Token { amount = kept } = fee;\n      console_write(\"fee hook: kept\", kept);\n      return kept;\n    }\n    Skip => {\n      close ledger;\n      return 0;\n    }\n  };\n}\n\ncomponent TokenProgram(\n  sender : Program[Transfer],\n  limit : Program[Inspect],\n  fee : Program[Custody],\n  receiver : Program[Deliver]\n) {\n  let (s1, tokens) = receive Token on sender;\n  let amount = borrow tokens as t { return t.amount; };\n  let asked = send amount on limit;\n  offer asked {\n    Allow => {\n      close asked;\n      let running = select Run on fee;\n      let handed = send tokens on running;\n      let (fee_done, returned) = receive Token on handed;\n      close fee_done;\n      let checked = approve(returned, amount);\n      let arriving = select Arrived on receiver;\n      let r_done = send checked on arriving;\n      close r_done;\n      let s_done = select Sent on s1;\n      close s_done;\n    }\n    Deny => {\n      close asked;\n      let skipping = select Skip on fee;\n      close skipping;\n      let nothing = select Nothing on receiver;\n      close nothing;\n      let blocked = select Blocked on s1;\n      let s_done = send tokens on blocked;\n      close s_done;\n    }\n  };\n}\n\ncomponent Receiver(ledger : Receiver[Deliver]) provides U64 {\n  offer ledger {\n    Arrived => {\n      let (done, tokens) = receive Token on ledger;\n      close done;\n      let Token { amount = got } = tokens;\n      console_write(\"receiver: received\", got);\n      return got;\n    }\n    Nothing => {\n      close ledger;\n      console_write(\"receiver: nothing arrived\");\n      return 0;\n    }\n  };\n}\n\narchitecture HookedToken {\n  instance sender = Sender;\n  instance token = TokenProgram;\n  instance limit_hook = LimitHook;\n  instance fee_hook = FeeHook;\n  instance receiver = Receiver;\n  process sender_run = sender;\n  process token_run = token;\n  process limit_run = limit_hook;\n  process fee_run = fee_hook;\n  process receiver_run = receiver;\n  protocol transfer = Transfer;\n  protocol inspect = Inspect;\n  protocol custody = Custody;\n  protocol deliver = Deliver;\n  role transfer.Sender = sender;\n  role transfer.Program = token;\n  role inspect.Program = token;\n  role inspect.Hook = limit_hook;\n  role custody.Program = token;\n  role custody.Hook = fee_hook;\n  role deliver.Program = token;\n  role deliver.Receiver = receiver;\n  entry amount : U64;\n  entry max_transfer : U64;\n  entry fee_bps : U64;\n  bind sender.ledger = transfer.Sender;\n  bind sender.amount = amount;\n  bind token.sender = transfer.Program;\n  bind token.limit = inspect.Program;\n  bind token.fee = custody.Program;\n  bind token.receiver = deliver.Program;\n  bind limit_hook.ledger = inspect.Hook;\n  bind limit_hook.max_transfer = max_transfer;\n  bind fee_hook.ledger = custody.Hook;\n  bind fee_hook.fee_bps = fee_bps;\n  bind receiver.ledger = deliver.Receiver;\n}\n\nprogram main = instantiate HookedToken;\n";
export const LAUNCHHOOKS_SOURCE = "// Launchpad hooks: the rules a launchpad runs at each step of a token launch.\n//\n// Modelled on the \"New school\" launch described in higher.fun's public docs.\n// This is our own reading of those docs, written in Phil. It is not\n// higher.fun's code and is not endorsed by them.\n//\n// A launch has three hook points:\n//\n//   on every buy       a sniper hook looks at when the buy happened and flags\n//                      or clears the buyer; a fee hook is handed the 1% trade\n//                      fee and splits it four ways.\n//   at graduation      a graduation hook is handed the liquidity and the\n//                      creator's locked allocation. It burns 70% of the\n//                      liquidity, locks 30%, and puts the creator's tokens on\n//                      a schedule: nothing for 7 days, then evenly over 30.\n//   at the end         holder rewards are paid out. Flagged buyers get none.\n//\n// Cash, tokens and liquidity are linear. Every unit of fee ends up in exactly\n// one of the four places, and the launch cannot keep any of it.\n\nrecord Cash mode linear {\n  amount : U64\n}\n\nrecord Token mode linear {\n  amount : U64\n}\n\nrecord Liquidity mode linear {\n  amount : U64\n}\n\ncallable Take(pot : Cash, part : U64) -> (Cash, Cash) {\n  requires part <= pot.amount;\n  outcomes { success (Cash, Cash) };\n}\n\nfn take(pot : Cash, part : U64) -> (Cash, Cash) satisfies Take {\n  let Cash { amount = total } = pot;\n  return (construct Cash { amount = part }, construct Cash { amount = total - part });\n}\n\n// One holder's part of the reward pot, by tokens held. Nobody holding means nothing to split.\ncallable ProRata(pot : U64, mine : U64, everyone : U64) -> U64 {\n  requires mine <= everyone;\n  requires pot <= 1000000;\n  requires everyone <= 1000000000;\n  outcomes { success U64 };\n}\n\nfn pro_rata(pot : U64, mine : U64, everyone : U64) -> U64 satisfies ProRata {\n  if eq(everyone, 0) {\n    return 0;\n  } else {\n    return pot * mine / everyone;\n  };\n}\n\ncallable Pool(a : Cash, b : Cash) -> Cash {\n  outcomes { success Cash };\n}\n\nfn pool(a : Cash, b : Cash) -> Cash satisfies Pool {\n  let Cash { amount = x } = a;\n  let Cash { amount = y } = b;\n  return construct Cash { amount = x + y };\n}\n\n// The trade fee is 1% of what the buyer pays.\ncallable TradeFee(payment : U64) -> U64 {\n  requires payment <= 1000000000000;\n  outcomes { success U64 };\n}\n\nfn trade_fee(payment : U64) -> U64 satisfies TradeFee {\n  return payment / 100;\n}\n\n// The launch checks what the fee hook hands back for holders: a quarter of\n// the fee if the creator keeps their share, half if the creator gives it up.\ncallable HolderShare(returned : Cash, fee : U64, creator_keeps : Bool) -> Cash {\n  requires returned.amount <= fee;\n  requires returned.amount * 4 + 3 >= fee;\n  outcomes { success Cash };\n}\n\nfn holder_share(returned : Cash, fee : U64, creator_keeps : Bool) -> Cash satisfies HolderShare {\n  return returned;\n}\n\n// At graduation 30% of the liquidity is locked and the rest, at least 70%, is burned.\ncallable Burn(liquidity : Liquidity) -> (Liquidity, Liquidity) {\n  requires liquidity.amount <= 1000000000000;\n  outcomes { success (Liquidity, Liquidity) };\n}\n\nfn burn(liquidity : Liquidity) -> (Liquidity, Liquidity) satisfies Burn {\n  let Liquidity { amount = total } = liquidity;\n  let locked = total * 30 / 100;\n  return (construct Liquidity { amount = total - locked }, construct Liquidity { amount = locked });\n}\n\n// How much of the creator's locked allocation has unlocked `day` days after graduation.\ncallable CreatorUnlocked(locked : U64, day : U64) -> U64 {\n  requires locked <= 1000000000000;\n  outcomes { success U64 };\n}\n\nfn creator_unlocked(locked : U64, day : U64) -> U64 satisfies CreatorUnlocked {\n  if le(day, 7) {\n    return 0;\n  } else {\n    if ge(day, 37) {\n      return locked;\n    } else {\n      return locked * (day - 7) / 30;\n    };\n  };\n}\n\n// A buyer and the launch.\nprotocol Buy {\n  role Buyer = send (payment : Cash) then receive (tokens : Token) then offer {\n    Reward => receive (reward : Cash) then end Rewarded |\n    NoReward => end Unrewarded\n  };\n  role Launch = receive (payment : Cash) then send (tokens : Token) then select {\n    Reward => send (reward : Cash) then end Rewarded |\n    NoReward => end Unrewarded\n  };\n}\n\n// Sniper hook: told which block a buy landed in, it flags or clears the buyer.\nprotocol Screen {\n  role Launch = recursive Next = select {\n    Check => send (block : U64) then offer {\n      Flag => continue Next |\n      Clear => continue Next\n    } |\n    Finished => end Finished\n  };\n  role Hook = recursive Next = offer {\n    Check => receive (block : U64) then select {\n      Flag => continue Next |\n      Clear => continue Next\n    } |\n    Finished => end Finished\n  };\n}\n\n// Fee hook: handed each trade fee, it hands back the holders' share and keeps the rest to pay out.\nprotocol Fees {\n  role Launch = recursive Next = select {\n    Trade => send (fee : Cash) then receive (holders : Cash) then continue Next |\n    Finished => end Finished\n  };\n  role Hook = recursive Next = offer {\n    Trade => receive (fee : Cash) then send (holders : Cash) then continue Next |\n    Finished => end Finished\n  };\n}\n\n// Graduation hook: handed the liquidity and the creator's locked tokens, or told the launch did not graduate.\nprotocol Graduation {\n  role Launch = select {\n    Graduate => send (liquidity : Liquidity) then send (creator_tokens : Token) then end Graduated |\n    Stay => end Ungraduated\n  };\n  role Hook = offer {\n    Graduate => receive (liquidity : Liquidity) then receive (creator_tokens : Token) then end Graduated |\n    Stay => end Ungraduated\n  };\n}\n\ncomponent Buyer(launch : Buyer[Buy], spend : {v : U64 | v <= 1000000}) provides U64 {\n  let paid = send construct Cash { amount = spend } on launch;\n  let (deciding, tokens) = receive Token on paid;\n  let Token { amount = got } = tokens;\n  offer deciding {\n    Reward => {\n      let (done, reward) = receive Cash on deciding;\n      close done;\n      let Cash { amount = earned } = reward;\n      console_write(\"bought\", got, \"tokens, holder reward\", earned);\n      return earned;\n    }\n    NoReward => {\n      close deciding;\n      console_write(\"bought\", got, \"tokens, no holder reward\");\n      return 0;\n    }\n  };\n}\n\ncomponent SniperHook(launch : Hook[Screen], sniper_window : U64) {\n  loop state (ep = launch) {\n    offer ep {\n      Check => {\n        let (deciding, block) = receive U64 on ep;\n        if le(block, sniper_window) {\n          let flagged = select Flag on deciding;\n          console_write(\"sniper hook: buy in block\", block, \"flagged\");\n          continue (flagged);\n        } else {\n          let cleared = select Clear on deciding;\n          continue (cleared);\n        };\n      }\n      Finished => {\n        close ep;\n        break;\n      }\n    };\n  };\n}\n\ncomponent FeeHook(launch : Hook[Fees], creator_keeps : Bool) provides U64 {\n  let total = loop state (ep = launch, creator : U64 = 0, platform : U64 = 0, amm : U64 = 0) {\n    offer ep {\n      Trade => {\n        let (returning, fee) = receive Cash on ep;\n        let whole = borrow fee as f { return f.amount; };\n        let quarter = whole / 4;\n        // A quarter each to the platform and the pool; the creator's quarter goes to the creator or to holders.\n        let (for_platform, rest1) = take(fee, quarter);\n        let (for_creator, rest2) = take(rest1, quarter);\n        let (for_holders, for_amm) = take(rest2, quarter);\n        let Cash { amount = p } = for_platform;\n        let Cash { amount = a } = for_amm;\n        if creator_keeps {\n          let Cash { amount = c } = for_creator;\n          let next = send for_holders on returning;\n          continue (next, creator + c, platform + p, amm + a);\n        } else {\n          let next = send pool(for_holders, for_creator) on returning;\n          continue (next, creator, platform + p, amm + a);\n        };\n      }\n      Finished => {\n        close ep;\n        console_write(\"fee hook: creator\", creator, \"platform\", platform, \"pool\", amm);\n        break (creator + platform + amm);\n      }\n    };\n  };\n  return total;\n}\n\ncomponent GraduationHook(launch : Hook[Graduation], check_day : U64) provides U64 {\n  offer launch {\n    Graduate => {\n      let (more, liquidity) = receive Liquidity on launch;\n      let (done, creator_tokens) = receive Token on more;\n      close done;\n      let (burned, locked) = burn(liquidity);\n      let Liquidity { amount = gone } = burned;\n      let Liquidity { amount = kept } = locked;\n      console_write(\"graduation hook: liquidity burned\", gone, \"locked\", kept);\n      let Token { amount = held } = creator_tokens;\n      let open = creator_unlocked(held, check_day);\n      console_write(\"graduation hook: creator lock\", held, \"tokens,\", open, \"unlocked on day\", check_day);\n      return gone;\n    }\n    Stay => {\n      close launch;\n      console_write(\"graduation hook: not graduated, nothing to do\");\n      return 0;\n    }\n  };\n}\n\ncomponent Launch(\n  early : Launch[Buy],\n  late : Launch[Buy],\n  screen : Launch[Screen],\n  fees : Launch[Fees],\n  graduation : Launch[Graduation],\n  late_block : U64,\n  target : U64,\n  creator_keeps : Bool,\n  creator_lock_pct : {v : U64 | v <= 10}\n) {\n  // First buy, in block 1.\n  let (e1, pay1) = receive Cash on early;\n  let spend1 = borrow pay1 as p { return p.amount; };\n  let asked1 = select Check on screen;\n  let s1 = send 1 on asked1;\n  let (screened1, flag1) = loop state (ep = s1) {\n    offer ep {\n      Flag => { break (ep, true); }\n      Clear => { break (ep, false); }\n    };\n  };\n  let fee1 = trade_fee(spend1);\n  let (fee_cash1, net1) = take(pay1, fee1);\n  let trading1 = select Trade on fees;\n  let f1 = send fee_cash1 on trading1;\n  let (f2, back1) = receive Cash on f1;\n  let holders1 = holder_share(back1, fee1, creator_keeps);\n  let tokens1 = (spend1 - fee1) * 100;\n  let e2 = send construct Token { amount = tokens1 } on e1;\n\n  // Second buy, in a later block.\n  let (l1, pay2) = receive Cash on late;\n  let spend2 = borrow pay2 as p { return p.amount; };\n  let asked2 = select Check on screened1;\n  let s2 = send late_block on asked2;\n  let (screened2, flag2) = loop state (ep = s2) {\n    offer ep {\n      Flag => { break (ep, true); }\n      Clear => { break (ep, false); }\n    };\n  };\n  let screen_done = select Finished on screened2;\n  close screen_done;\n  let fee2 = trade_fee(spend2);\n  let (fee_cash2, net2) = take(pay2, fee2);\n  let trading2 = select Trade on f2;\n  let f3 = send fee_cash2 on trading2;\n  let (f4, back2) = receive Cash on f3;\n  let holders2 = holder_share(back2, fee2, creator_keeps);\n  let fees_done = select Finished on f4;\n  close fees_done;\n  let tokens2 = (spend2 - fee2) * 100;\n  let l2 = send construct Token { amount = tokens2 } on l1;\n\n  // Graduation: enough cash in the curve.\n  let reserve = pool(net1, net2);\n  let raised = borrow reserve as r { return r.amount; };\n  let Cash { amount = into_pool } = reserve;\n  if ge(raised, target) {\n    let graduating = select Graduate on graduation;\n    let g1 = send construct Liquidity { amount = into_pool } on graduating;\n    let g2 = send construct Token { amount = (tokens1 + tokens2) * creator_lock_pct / 100 } on g1;\n    close g2;\n    console_write(\"launch: graduated with\", raised, \"in the curve\");\n  } else {\n    let staying = select Stay on graduation;\n    close staying;\n    console_write(\"launch: did not graduate,\", raised, \"of\", target);\n  };\n\n  // Holder rewards. Flagged buyers get nothing.\n  let rewards = pool(holders1, holders2);\n  let pot = borrow rewards as r { return r.amount; };\n  if flag1 {\n    let none = select NoReward on e2;\n    close none;\n    if flag2 {\n      let none2 = select NoReward on l2;\n      close none2;\n      let Cash { amount = unclaimed } = rewards;\n      console_write(\"launch: no eligible holders, unclaimed rewards\", unclaimed);\n    } else {\n      let paying = select Reward on l2;\n      let done = send rewards on paying;\n      close done;\n    };\n  } else {\n    if flag2 {\n      let none2 = select NoReward on l2;\n      close none2;\n      let paying = select Reward on e2;\n      let done = send rewards on paying;\n      close done;\n    } else {\n      // Both eligible: split by how many tokens each holds.\n      let (share1, share2) = take(rewards, pro_rata(pot, tokens1, tokens1 + tokens2));\n      let paying1 = select Reward on e2;\n      let done1 = send share1 on paying1;\n      close done1;\n      let paying2 = select Reward on l2;\n      let done2 = send share2 on paying2;\n      close done2;\n    };\n  };\n}\n\narchitecture HookedLaunch {\n  instance early_buyer = Buyer;\n  instance late_buyer = Buyer;\n  instance launch = Launch;\n  instance sniper_hook = SniperHook;\n  instance fee_hook = FeeHook;\n  instance graduation_hook = GraduationHook;\n  process early_run = early_buyer;\n  process late_run = late_buyer;\n  process launch_run = launch;\n  process sniper_run = sniper_hook;\n  process fee_run = fee_hook;\n  process graduation_run = graduation_hook;\n  protocol buy_early = Buy;\n  protocol buy_late = Buy;\n  protocol screening = Screen;\n  protocol fee_split = Fees;\n  protocol graduating = Graduation;\n  role buy_early.Buyer = early_buyer;\n  role buy_early.Launch = launch;\n  role buy_late.Buyer = late_buyer;\n  role buy_late.Launch = launch;\n  role screening.Launch = launch;\n  role screening.Hook = sniper_hook;\n  role fee_split.Launch = launch;\n  role fee_split.Hook = fee_hook;\n  role graduating.Launch = launch;\n  role graduating.Hook = graduation_hook;\n  entry early_spend : U64;\n  entry late_spend : U64;\n  entry late_block : U64;\n  entry sniper_window : U64;\n  entry target : U64;\n  entry creator_keeps : Bool;\n  entry creator_lock_pct : U64;\n  entry check_day : U64;\n  bind early_buyer.launch = buy_early.Buyer;\n  bind early_buyer.spend = early_spend;\n  bind late_buyer.launch = buy_late.Buyer;\n  bind late_buyer.spend = late_spend;\n  bind launch.early = buy_early.Launch;\n  bind launch.late = buy_late.Launch;\n  bind launch.screen = screening.Launch;\n  bind launch.fees = fee_split.Launch;\n  bind launch.graduation = graduating.Launch;\n  bind launch.late_block = late_block;\n  bind launch.target = target;\n  bind launch.creator_keeps = creator_keeps;\n  bind launch.creator_lock_pct = creator_lock_pct;\n  bind sniper_hook.launch = screening.Hook;\n  bind sniper_hook.sniper_window = sniper_window;\n  bind fee_hook.launch = fee_split.Hook;\n  bind fee_hook.creator_keeps = creator_keeps;\n  bind graduation_hook.launch = graduating.Hook;\n  bind graduation_hook.check_day = check_day;\n}\n\nprogram main = instantiate HookedLaunch;\n";
export const STOCKREWARDS_SOURCE = "// Stock rewards hook: pay holders in tokenized stock instead of cash.\n//\n// A token program collects the holders' share of trading fees. Each round it\n// hands that pot to a rewards hook. The hook asks a stock desk for a price,\n// buys as many units of tokenized stock as the pot affords, and hands the\n// stock to holders in proportion to the tokens they hold. Holders flagged as\n// snipers are left out. Cash that is too little to buy a unit is carried over\n// to the next round.\n//\n// The hook refuses to buy above a price limit: then the whole pot is carried\n// over. Cash and stock are linear, so the pot is fully accounted for (spent\n// or carried), and every unit of stock bought reaches a holder.\n\nrecord Cash mode linear {\n  amount : U64\n}\n\nrecord Stock mode linear {\n  units : U64\n}\n\ncallable Take(pot : Cash, part : U64) -> (Cash, Cash) {\n  requires part <= pot.amount;\n  outcomes { success (Cash, Cash) };\n}\n\nfn take(pot : Cash, part : U64) -> (Cash, Cash) satisfies Take {\n  let Cash { amount = total } = pot;\n  return (construct Cash { amount = part }, construct Cash { amount = total - part });\n}\n\ncallable Cut(lot : Stock, part : U64) -> (Stock, Stock) {\n  requires part <= lot.units;\n  outcomes { success (Stock, Stock) };\n}\n\nfn cut(lot : Stock, part : U64) -> (Stock, Stock) satisfies Cut {\n  let Stock { units = total } = lot;\n  return (construct Stock { units = part }, construct Stock { units = total - part });\n}\n\n// How many units to buy: whole units only, never more than the desk has,\n// and none at all when nobody is eligible to receive them.\ncallable Affordable(pot : U64, price : U64, available : U64, eligible : U64) -> U64 {\n  requires price > 0;\n  outcomes { success U64 };\n}\n\nfn affordable(pot : U64, price : U64, available : U64, eligible : U64) -> U64 satisfies Affordable {\n  if eq(eligible, 0) {\n    return 0;\n  } else {\n    if le(pot / price, available) {\n      return pot / price;\n    } else {\n      return available;\n    };\n  };\n}\n\n// The hook checks the desk delivered exactly what was paid for.\ncallable Delivered(lot : Stock, ordered : U64) -> Stock {\n  requires lot.units == ordered;\n  outcomes { success Stock };\n}\n\nfn delivered(lot : Stock, ordered : U64) -> Stock satisfies Delivered {\n  return lot;\n}\n\n// The desk checks it was paid the quoted price for every unit.\ncallable Paid(payment : Cash, units : U64, price : U64) -> Cash {\n  requires units <= 1000000000;\n  requires price <= 1000000000;\n  requires payment.amount == units * price;\n  outcomes { success Cash };\n}\n\nfn paid(payment : Cash, units : U64, price : U64) -> Cash satisfies Paid {\n  return payment;\n}\n\n// One holder's part of the stock, by tokens held.\ncallable ProRata(units : U64, mine : U64, everyone : U64) -> U64 {\n  requires mine <= everyone;\n  requires units <= 1000000000;\n  requires everyone <= 1000000000;\n  outcomes { success U64 };\n}\n\nfn pro_rata(units : U64, mine : U64, everyone : U64) -> U64 satisfies ProRata {\n  if eq(everyone, 0) {\n    return 0;\n  } else {\n    return units * mine / everyone;\n  };\n}\n\n// Token program and rewards hook: here is the pot and who holds what; hand back what you did not spend.\nprotocol Fund {\n  role Program = send (pot : Cash) then send (first_holding : U64) then send (second_holding : U64) then receive (carry : Cash) then end Funded;\n  role Hook = receive (pot : Cash) then receive (first_holding : U64) then receive (second_holding : U64) then send (carry : Cash) then end Funded;\n}\n\n// Rewards hook and stock desk: a quote, then buy or pass.\nprotocol Quote {\n  role Desk = send (price : U64) then send (available : U64) then offer {\n    Buy => receive (units : U64) then receive (payment : Cash) then send (lot : Stock) then end Sold |\n    Pass => end Passed\n  };\n  role Hook = receive (price : U64) then receive (available : U64) then select {\n    Buy => send (units : U64) then send (payment : Cash) then receive (lot : Stock) then end Sold |\n    Pass => end Passed\n  };\n}\n\n// Rewards hook and one holder.\nprotocol Reward {\n  role Hook = select {\n    Shares => send (lot : Stock) then end Rewarded |\n    Nothing => end Unrewarded\n  };\n  role Holder = offer {\n    Shares => receive (lot : Stock) then end Rewarded |\n    Nothing => end Unrewarded\n  };\n}\n\ncomponent TokenProgram(\n  hook : Program[Fund],\n  pot : {v : U64 | v <= 1000000000},\n  first_tokens : {v : U64 | v <= 500000000},\n  second_tokens : {v : U64 | v <= 500000000},\n  second_flagged : Bool\n) provides Cash {\n  let funded = send construct Cash { amount = pot } on hook;\n  let told = send first_tokens on funded;\n  // A flagged holder counts as holding nothing for rewards.\n  if second_flagged {\n    let asked = send 0 on told;\n    let (done, carry) = receive Cash on asked;\n    close done;\n    let left = borrow carry as c { return c.amount; };\n    console_write(\"token program: carried to next round\", left);\n    return carry;\n  } else {\n    let asked = send second_tokens on told;\n    let (done, carry) = receive Cash on asked;\n    close done;\n    let left = borrow carry as c { return c.amount; };\n    console_write(\"token program: carried to next round\", left);\n    return carry;\n  };\n}\n\ncomponent StockDesk(hook : Desk[Quote], stock_price : {v : U64 | v > 0}, inventory : {v : U64 | v <= 1000000000}) provides U64 {\n  let shelf = construct Stock { units = inventory };\n  let quoted = send stock_price on hook;\n  let listed = send inventory on quoted;\n  offer listed {\n    Buy => {\n      let (paying, units) = receive U64 on listed;\n      let (delivering, payment) = receive Cash on paying;\n      let Cash { amount = taken } = paid(payment, units, stock_price);\n      let (lot, rest) = cut(shelf, units);\n      let done = send lot on delivering;\n      close done;\n      let Stock { units = left } = rest;\n      console_write(\"stock desk: sold\", units, \"units for\", taken);\n      return taken;\n    }\n    Pass => {\n      close listed;\n      let Stock { units = left } = shelf;\n      console_write(\"stock desk: no sale\");\n      return 0;\n    }\n  };\n}\n\ncomponent RewardsHook(\n  token : Hook[Fund],\n  desk : Hook[Quote],\n  first : Hook[Reward],\n  second : Hook[Reward],\n  max_price : U64\n) {\n  let (t1, pot) = receive Cash on token;\n  let (t2, first_holding) = receive U64 on t1;\n  let (t3, second_holding) = receive U64 on t2;\n  let (d1, price) = receive U64 on desk;\n  let (d2, available) = receive U64 on d1;\n  let funds = borrow pot as p { return p.amount; };\n  if le(price, max_price) {\n    let everyone = first_holding + second_holding;\n    let units = affordable(funds, price, available, everyone);\n    if gt(units, 0) {\n      let (payment, carry) = take(pot, units * price);\n      let buying = select Buy on d2;\n      let d3 = send units on buying;\n      let d4 = send payment on d3;\n      let (d5, lot) = receive Stock on d4;\n      close d5;\n      let checked = delivered(lot, units);\n      let t_done = send carry on t3;\n      close t_done;\n      // Split by tokens held. Rounding goes to the second holder unless they are left out.\n      if eq(second_holding, 0) {\n        let none = select Nothing on second;\n        close none;\n        let giving = select Shares on first;\n        let done = send checked on giving;\n        close done;\n      } else {\n        let (for_first, for_second) = cut(checked, pro_rata(units, first_holding, everyone));\n        let giving2 = select Shares on second;\n        let done2 = send for_second on giving2;\n        close done2;\n        let giving1 = select Shares on first;\n        let done1 = send for_first on giving1;\n        close done1;\n      };\n    } else {\n      let passing = select Pass on d2;\n      close passing;\n      let t_done = send pot on t3;\n      close t_done;\n      let none1 = select Nothing on first;\n      close none1;\n      let none2 = select Nothing on second;\n      close none2;\n      if eq(everyone, 0) {\n        console_write(\"rewards hook: no eligible holders, nothing bought\");\n      } else {\n        console_write(\"rewards hook: nothing bought, the pot or the desk's stock is too small\");\n      };\n    };\n  } else {\n    let passing = select Pass on d2;\n    close passing;\n    let t_done = send pot on t3;\n    close t_done;\n    let none1 = select Nothing on first;\n    close none1;\n    let none2 = select Nothing on second;\n    close none2;\n    console_write(\"rewards hook: price\", price, \"is above the limit of\", max_price);\n  };\n}\n\ncomponent Holder(hook : Holder[Reward]) provides U64 {\n  offer hook {\n    Shares => {\n      let (done, lot) = receive Stock on hook;\n      close done;\n      let Stock { units = got } = lot;\n      console_write(\"received\", got, \"units of stock\");\n      return got;\n    }\n    Nothing => {\n      close hook;\n      console_write(\"received nothing this round\");\n      return 0;\n    }\n  };\n}\n\narchitecture StockRewards {\n  instance token = TokenProgram;\n  instance rewards_hook = RewardsHook;\n  instance stock_desk = StockDesk;\n  instance first_holder = Holder;\n  instance second_holder = Holder;\n  process token_run = token;\n  process hook_run = rewards_hook;\n  process desk_run = stock_desk;\n  process first_run = first_holder;\n  process second_run = second_holder;\n  protocol fund = Fund;\n  protocol quote = Quote;\n  protocol reward_first = Reward;\n  protocol reward_second = Reward;\n  role fund.Program = token;\n  role fund.Hook = rewards_hook;\n  role quote.Desk = stock_desk;\n  role quote.Hook = rewards_hook;\n  role reward_first.Hook = rewards_hook;\n  role reward_first.Holder = first_holder;\n  role reward_second.Hook = rewards_hook;\n  role reward_second.Holder = second_holder;\n  entry pot : U64;\n  entry stock_price : U64;\n  entry max_price : U64;\n  entry inventory : U64;\n  entry first_tokens : U64;\n  entry second_tokens : U64;\n  entry second_flagged : Bool;\n  bind token.hook = fund.Program;\n  bind token.pot = pot;\n  bind token.first_tokens = first_tokens;\n  bind token.second_tokens = second_tokens;\n  bind token.second_flagged = second_flagged;\n  bind stock_desk.hook = quote.Desk;\n  bind stock_desk.stock_price = stock_price;\n  bind stock_desk.inventory = inventory;\n  bind rewards_hook.token = fund.Hook;\n  bind rewards_hook.desk = quote.Hook;\n  bind rewards_hook.first = reward_first.Hook;\n  bind rewards_hook.second = reward_second.Hook;\n  bind rewards_hook.max_price = max_price;\n  bind first_holder.hook = reward_first.Holder;\n  bind second_holder.hook = reward_second.Holder;\n}\n\nprogram main = instantiate StockRewards;\n";
export const VESTING_SOURCE = "// Token vesting with revocation.\n//\n// A grantor locks tokens in a vault for a beneficiary. The tokens are released\n// in equal parts, one per period. Before each period the grantor may revoke:\n// what has not vested yet goes back to the grantor, what has vested stays with\n// the beneficiary. Tokens are linear, so the two shares always add up to the\n// grant: nothing is stranded in the vault.\n\nrecord Token mode linear {\n  amount : U64\n}\n\ncallable Carve(pot : Token, part : U64) -> (Token, Token) {\n  requires part <= pot.amount;\n  outcomes { success (Token, Token) };\n}\n\nfn carve(pot : Token, part : U64) -> (Token, Token) satisfies Carve {\n  let Token { amount = total } = pot;\n  return (construct Token { amount = part }, construct Token { amount = total - part });\n}\n\ncallable Join(a : Token, b : Token) -> Token {\n  outcomes { success Token };\n}\n\nfn combine(a : Token, b : Token) -> Token satisfies Join {\n  let Token { amount = x } = a;\n  let Token { amount = y } = b;\n  return construct Token { amount = x + y };\n}\n\n// A vault may only be emptied out when it holds nothing.\ncallable Retire(pot : Token) -> U64 {\n  requires pot.amount == 0;\n  outcomes { success U64 };\n}\n\nfn retire(pot : Token) -> U64 satisfies Retire {\n  let Token { amount } = pot;\n  return amount;\n}\n\n// Grantor and vault. Before every period the grantor keeps the grant or revokes it.\nprotocol Grant {\n  role Grantor = send (award : Token) then recursive Period = offer {\n    Due => select {\n      Keep => continue Period |\n      Revoke => receive (unvested : Token) then end Revoked\n    } |\n    Complete => end Vested\n  };\n  role Vault = receive (award : Token) then recursive Period = select {\n    Due => offer {\n      Keep => continue Period |\n      Revoke => send (unvested : Token) then end Revoked\n    } |\n    Complete => end Vested\n  };\n}\n\n// Vault and beneficiary. Each period that vests delivers one part.\nprotocol Payout {\n  role Vault = recursive Period = select {\n    Vested => send (part : Token) then continue Period |\n    Finished => end Finished\n  };\n  role Beneficiary = recursive Period = offer {\n    Vested => receive (part : Token) then continue Period |\n    Finished => end Finished\n  };\n}\n\ncomponent Grantor(vault : Grantor[Grant], total : {v : U64 | v <= 1000000000}, revoke_after : U64) provides Token {\n  let locked = send construct Token { amount = total } on vault;\n  let back = loop state (ep = locked, seen : U64 = 0) {\n    offer ep {\n      Due => {\n        if eq(seen, revoke_after) {\n          let revoking = select Revoke on ep;\n          let (done, unvested) = receive Token on revoking;\n          close done;\n          console_write(\"grantor revoked after\", seen, \"periods\");\n          break (unvested);\n        } else {\n          let keeping = select Keep on ep;\n          continue (keeping, seen + 1);\n        };\n      }\n      Complete => {\n        close ep;\n        break (construct Token { amount = 0 });\n      }\n    };\n  };\n  return back;\n}\n\ncomponent Vault(grantor : Vault[Grant], beneficiary : Vault[Payout], periods : {v : U64 | v > 0}) {\n  let (g1, award) = receive Token on grantor;\n  let total = borrow award as t { return t.amount; };\n  let each = total / periods;\n  loop state (g = g1, b = beneficiary, pot = award, period : U64 = 1) {\n    if gt(period, periods) {\n      let g_done = select Complete on g;\n      close g_done;\n      let b_done = select Finished on b;\n      close b_done;\n      let none = retire(pot);\n      break;\n    } else {\n      let asked = select Due on g;\n      offer asked {\n        Keep => {\n          // The last period releases whatever is left, so rounding never strands a token.\n          let left = borrow pot as p { return p.amount; };\n          if eq(period, periods) {\n            let (part, rest) = carve(pot, left);\n            let b1 = select Vested on b;\n            let b2 = send part on b1;\n            continue (asked, b2, rest, period + 1);\n          } else {\n            let (part, rest) = carve(pot, each);\n            let b1 = select Vested on b;\n            let b2 = send part on b1;\n            continue (asked, b2, rest, period + 1);\n          };\n        }\n        Revoke => {\n          let g_done = send pot on asked;\n          close g_done;\n          let b_done = select Finished on b;\n          close b_done;\n          break;\n        }\n      };\n    };\n  };\n}\n\ncomponent Beneficiary(vault : Beneficiary[Payout]) provides Token {\n  let held = loop state (ep = vault, mine = construct Token { amount = 0 }) {\n    offer ep {\n      Vested => {\n        let (next, part) = receive Token on ep;\n        continue (next, combine(mine, part));\n      }\n      Finished => {\n        close ep;\n        break (mine);\n      }\n    };\n  };\n  let amount = borrow held as h { return h.amount; };\n  console_write(\"beneficiary holds\", amount);\n  return held;\n}\n\narchitecture Vesting {\n  instance grantor = Grantor;\n  instance vault = Vault;\n  instance beneficiary = Beneficiary;\n  process grantor_run = grantor;\n  process vault_run = vault;\n  process beneficiary_run = beneficiary;\n  protocol award = Grant;\n  protocol payout = Payout;\n  role award.Grantor = grantor;\n  role award.Vault = vault;\n  role payout.Vault = vault;\n  role payout.Beneficiary = beneficiary;\n  entry total : U64;\n  entry periods : U64;\n  entry revoke_after : U64;\n  bind grantor.vault = award.Grantor;\n  bind grantor.total = total;\n  bind grantor.revoke_after = revoke_after;\n  bind vault.grantor = award.Vault;\n  bind vault.beneficiary = payout.Vault;\n  bind vault.periods = periods;\n  bind beneficiary.vault = payout.Beneficiary;\n}\n\nprogram main = instantiate Vesting;\n";
export const MULTISIG_SOURCE = "// A 2-of-3 treasury.\n//\n// Three signers vote on one payment from a shared treasury. The vault pays the\n// payee only when at least two approve and the treasury can cover the amount.\n// Otherwise nothing leaves. Cash is linear, so the payment and what stays in\n// the treasury always add up to what was there before.\n\nrecord Cash mode linear {\n  amount : U64\n}\n\n// The only way cash leaves the treasury. Both conditions are promises the vault must keep.\ncallable PayOut(treasury : Cash, amount : U64, approvals : U64) -> (Cash, Cash) {\n  requires approvals >= 2;\n  requires amount <= treasury.amount;\n  outcomes { success (Cash, Cash) };\n}\n\nfn pay_out(treasury : Cash, amount : U64, approvals : U64) -> (Cash, Cash) satisfies PayOut {\n  let Cash { amount = total } = treasury;\n  return (construct Cash { amount = amount }, construct Cash { amount = total - amount });\n}\n\n// Vault and one signer: here is the proposal, how do you vote?\nprotocol Ballot {\n  role Vault = send (amount : U64) then offer {\n    Approve => end Voted |\n    Reject => end Voted\n  };\n  role Signer = receive (amount : U64) then select {\n    Approve => end Voted |\n    Reject => end Voted\n  };\n}\n\n// Vault and payee: the outcome, and the cash if it passed.\nprotocol Payment {\n  role Vault = select {\n    Paid => send (cash : Cash) then end Paid |\n    Denied => end Denied\n  };\n  role Payee = offer {\n    Paid => receive (cash : Cash) then end Paid |\n    Denied => end Denied\n  };\n}\n\ncomponent Signer(vault : Signer[Ballot], approves : Bool) {\n  let (asked, amount) = receive U64 on vault;\n  if approves {\n    let voted = select Approve on asked;\n    close voted;\n  } else {\n    let voted = select Reject on asked;\n    close voted;\n  };\n}\n\ncomponent Vault(\n  first : Vault[Ballot],\n  second : Vault[Ballot],\n  third : Vault[Ballot],\n  payee : Vault[Payment],\n  funds : U64,\n  amount : U64\n) provides Cash {\n  let treasury = construct Cash { amount = funds };\n  // Ask each signer in turn and count the approvals.\n  let asked_a = send amount on first;\n  let after_a = loop state (ep = asked_a, count : U64 = 0) {\n    offer ep {\n      Approve => {\n        close ep;\n        break (count + 1);\n      }\n      Reject => {\n        close ep;\n        break (count);\n      }\n    };\n  };\n  let asked_b = send amount on second;\n  let after_b = loop state (ep = asked_b, count : U64 = after_a) {\n    offer ep {\n      Approve => {\n        close ep;\n        break (count + 1);\n      }\n      Reject => {\n        close ep;\n        break (count);\n      }\n    };\n  };\n  let asked_c = send amount on third;\n  let approvals = loop state (ep = asked_c, count : U64 = after_b) {\n    offer ep {\n      Approve => {\n        close ep;\n        break (count + 1);\n      }\n      Reject => {\n        close ep;\n        break (count);\n      }\n    };\n  };\n  console_write(\"approvals:\", approvals, \"of 3\");\n  if ge(approvals, 2) {\n    if ge(funds, amount) {\n      let (payment, kept) = pay_out(treasury, amount, approvals);\n      let paying = select Paid on payee;\n      let done = send payment on paying;\n      close done;\n      return kept;\n    } else {\n      // Approved, but the treasury cannot cover it: nothing leaves.\n      let denied = select Denied on payee;\n      close denied;\n      console_write(\"approved but not covered\");\n      return treasury;\n    };\n  } else {\n    let denied = select Denied on payee;\n    close denied;\n    return treasury;\n  };\n}\n\ncomponent Payee(vault : Payee[Payment]) provides U64 {\n  offer vault {\n    Paid => {\n      let (done, cash) = receive Cash on vault;\n      close done;\n      let Cash { amount = got } = cash;\n      console_write(\"payee received\", got);\n      return got;\n    }\n    Denied => {\n      close vault;\n      console_write(\"payment denied\");\n      return 0;\n    }\n  };\n}\n\narchitecture Treasury {\n  instance alice = Signer;\n  instance bob = Signer;\n  instance carol = Signer;\n  instance vault = Vault;\n  instance payee = Payee;\n  process alice_run = alice;\n  process bob_run = bob;\n  process carol_run = carol;\n  process vault_run = vault;\n  process payee_run = payee;\n  protocol ballot_a = Ballot;\n  protocol ballot_b = Ballot;\n  protocol ballot_c = Ballot;\n  protocol payment = Payment;\n  role ballot_a.Vault = vault;\n  role ballot_a.Signer = alice;\n  role ballot_b.Vault = vault;\n  role ballot_b.Signer = bob;\n  role ballot_c.Vault = vault;\n  role ballot_c.Signer = carol;\n  role payment.Vault = vault;\n  role payment.Payee = payee;\n  entry funds : U64;\n  entry amount : U64;\n  entry alice_approves : Bool;\n  entry bob_approves : Bool;\n  entry carol_approves : Bool;\n  bind alice.vault = ballot_a.Signer;\n  bind alice.approves = alice_approves;\n  bind bob.vault = ballot_b.Signer;\n  bind bob.approves = bob_approves;\n  bind carol.vault = ballot_c.Signer;\n  bind carol.approves = carol_approves;\n  bind vault.first = ballot_a.Vault;\n  bind vault.second = ballot_b.Vault;\n  bind vault.third = ballot_c.Vault;\n  bind vault.payee = payment.Vault;\n  bind payee.vault = payment.Payee;\n  bind vault.funds = funds;\n  bind vault.amount = amount;\n}\n\nprogram main = instantiate Treasury;\n";
export const AUCTION_SOURCE = "// A sealed-bid auction with a reserve price.\n//\n// A seller hands an item to an auctioneer and names a reserve. Two bidders each\n// lock their bid in cash. The higher bid wins if it meets the reserve: the\n// winner gets the item, the seller gets the winning bid, the loser gets their\n// cash back. If no bid meets the reserve, everything goes back where it came\n// from. The item and the cash are linear, so no path can keep a losing bid or\n// hand the item to two people.\n\nrecord Item mode linear {\n  id : U64\n}\n\nrecord Cash mode linear {\n  amount : U64\n}\n\n// The item only changes hands for a bid that meets the reserve and beats the other bid.\ncallable Award(winning : Cash, losing : U64, reserve : U64) -> Cash {\n  requires winning.amount >= reserve;\n  requires winning.amount >= losing;\n  outcomes { success Cash };\n}\n\nfn award(winning : Cash, losing : U64, reserve : U64) -> Cash satisfies Award {\n  return winning;\n}\n\n// Seller and auctioneer.\nprotocol Sale {\n  role Seller = send (reserve : U64) then send (item : Item) then offer {\n    Sold => receive (proceeds : Cash) then end Sold |\n    Unsold => receive (item : Item) then end Unsold\n  };\n  role Auctioneer = receive (reserve : U64) then receive (item : Item) then select {\n    Sold => send (proceeds : Cash) then end Sold |\n    Unsold => send (item : Item) then end Unsold\n  };\n}\n\n// One bidder and the auctioneer. The bid is real cash, held until the result.\nprotocol Bid {\n  role Bidder = send (bid : Cash) then offer {\n    Won => receive (item : Item) then end Won |\n    Lost => receive (refund : Cash) then end Lost\n  };\n  role Auctioneer = receive (bid : Cash) then select {\n    Won => send (item : Item) then end Won |\n    Lost => send (refund : Cash) then end Lost\n  };\n}\n\ncomponent Seller(house : Seller[Sale], reserve : U64) provides U64 {\n  let named = send reserve on house;\n  let handed = send construct Item { id = 1 } on named;\n  offer handed {\n    Sold => {\n      let (done, proceeds) = receive Cash on handed;\n      close done;\n      let Cash { amount = got } = proceeds;\n      console_write(\"seller received\", got);\n      return got;\n    }\n    Unsold => {\n      let (done, item) = receive Item on handed;\n      close done;\n      let Item { id } = item;\n      console_write(\"no sale: the seller has the item back\");\n      return 0;\n    }\n  };\n}\n\ncomponent Bidder(house : Bidder[Bid], offer_amount : U64) provides U64 {\n  let placed = send construct Cash { amount = offer_amount } on house;\n  offer placed {\n    Won => {\n      let (done, item) = receive Item on placed;\n      close done;\n      let Item { id } = item;\n      console_write(\"won the item for\", offer_amount);\n      return 1;\n    }\n    Lost => {\n      let (done, refund) = receive Cash on placed;\n      close done;\n      let Cash { amount = back } = refund;\n      console_write(\"lost, refunded\", back);\n      return 0;\n    }\n  };\n}\n\ncomponent Auctioneer(seller : Auctioneer[Sale], left : Auctioneer[Bid], right : Auctioneer[Bid]) {\n  let (s1, reserve) = receive U64 on seller;\n  let (s2, item) = receive Item on s1;\n  let (l1, left_bid) = receive Cash on left;\n  let (r1, right_bid) = receive Cash on right;\n  let l = borrow left_bid as c { return c.amount; };\n  let r = borrow right_bid as c { return c.amount; };\n  // The higher bid is the candidate; a tie goes to the left bidder.\n  if ge(l, r) {\n    if ge(l, reserve) {\n      let winning = award(left_bid, r, reserve);\n      let l2 = select Won on l1;\n      let l3 = send item on l2;\n      close l3;\n      let r2 = select Lost on r1;\n      let r3 = send right_bid on r2;\n      close r3;\n      let s3 = select Sold on s2;\n      let s4 = send winning on s3;\n      close s4;\n    } else {\n      let l2 = select Lost on l1;\n      let l3 = send left_bid on l2;\n      close l3;\n      let r2 = select Lost on r1;\n      let r3 = send right_bid on r2;\n      close r3;\n      let s3 = select Unsold on s2;\n      let s4 = send item on s3;\n      close s4;\n    };\n  } else {\n    if ge(r, reserve) {\n      let winning = award(right_bid, l, reserve);\n      let r2 = select Won on r1;\n      let r3 = send item on r2;\n      close r3;\n      let l2 = select Lost on l1;\n      let l3 = send left_bid on l2;\n      close l3;\n      let s3 = select Sold on s2;\n      let s4 = send winning on s3;\n      close s4;\n    } else {\n      let l2 = select Lost on l1;\n      let l3 = send left_bid on l2;\n      close l3;\n      let r2 = select Lost on r1;\n      let r3 = send right_bid on r2;\n      close r3;\n      let s3 = select Unsold on s2;\n      let s4 = send item on s3;\n      close s4;\n    };\n  };\n}\n\narchitecture AuctionHouse {\n  instance seller = Seller;\n  instance ann = Bidder;\n  instance ben = Bidder;\n  instance auctioneer = Auctioneer;\n  process seller_run = seller;\n  process ann_run = ann;\n  process ben_run = ben;\n  process auctioneer_run = auctioneer;\n  protocol sale = Sale;\n  protocol bid_ann = Bid;\n  protocol bid_ben = Bid;\n  role sale.Seller = seller;\n  role sale.Auctioneer = auctioneer;\n  role bid_ann.Bidder = ann;\n  role bid_ann.Auctioneer = auctioneer;\n  role bid_ben.Bidder = ben;\n  role bid_ben.Auctioneer = auctioneer;\n  entry reserve : U64;\n  entry ann_bid : U64;\n  entry ben_bid : U64;\n  bind seller.house = sale.Seller;\n  bind seller.reserve = reserve;\n  bind ann.house = bid_ann.Bidder;\n  bind ann.offer_amount = ann_bid;\n  bind ben.house = bid_ben.Bidder;\n  bind ben.offer_amount = ben_bid;\n  bind auctioneer.seller = sale.Auctioneer;\n  bind auctioneer.left = bid_ann.Auctioneer;\n  bind auctioneer.right = bid_ben.Auctioneer;\n}\n\nprogram main = instantiate AuctionHouse;\n";
export const LAUNCH_SOURCE = "// A bonding-curve token launch.\n//\n// Tokens are minted along a straight price curve: each token costs a little\n// more than the one before it. A buyer buys in rounds. If the whole supply\n// sells before time runs out, the launch graduates: the cash collected and a\n// matching batch of tokens go to a liquidity pool. If it does not, the launch\n// fails and the buyer gets all their cash back in exchange for the tokens.\n// Cash and tokens are linear, so the curve cannot keep the cash from a failed\n// launch or mint tokens it was not paid for.\n\nrecord Token mode linear {\n  amount : U64\n}\n\nrecord Cash mode linear {\n  amount : U64\n}\n\n// The price of `count` tokens when `sold` are already out:\n// each token costs base + slope * (number sold before it).\ncallable Quote(sold : U64, count : U64, base : U64, slope : U64) -> U64 {\n  requires count > 0;\n  requires sold <= 1000000;\n  requires count <= 1000000;\n  requires base <= 1000000;\n  requires slope <= 1000;\n  outcomes { success U64 };\n}\n\nfn quote(sold : U64, count : U64, base : U64, slope : U64) -> U64 satisfies Quote {\n  return count * base + slope * (count * sold + count * (count - 1) / 2);\n}\n\n// Minting is tied to payment: tokens only come into being against exactly the quoted cash.\ncallable Mint(payment : Cash, due : U64, count : U64) -> (Token, Cash) {\n  requires payment.amount == due;\n  outcomes { success (Token, Cash) };\n}\n\nfn mint(payment : Cash, due : U64, count : U64) -> (Token, Cash) satisfies Mint {\n  return (construct Token { amount = count }, payment);\n}\n\n// A refund burns the returned tokens and must hand back the whole reserve.\ncallable Refund(returned : Token, sold : U64, reserve : Cash) -> Cash {\n  requires returned.amount == sold;\n  outcomes { success Cash };\n}\n\nfn refund(returned : Token, sold : U64, reserve : Cash) -> Cash satisfies Refund {\n  let Token { amount } = returned;\n  return reserve;\n}\n\ncallable Add(a : Cash, b : Cash) -> Cash {\n  outcomes { success Cash };\n}\n\nfn add(a : Cash, b : Cash) -> Cash satisfies Add {\n  let Cash { amount = x } = a;\n  let Cash { amount = y } = b;\n  return construct Cash { amount = x + y };\n}\n\ncallable Stack(a : Token, b : Token) -> Token {\n  outcomes { success Token };\n}\n\nfn stack(a : Token, b : Token) -> Token satisfies Stack {\n  let Token { amount = x } = a;\n  let Token { amount = y } = b;\n  return construct Token { amount = x + y };\n}\n\ncallable Pay(wallet : Cash, due : U64) -> (Cash, Cash) {\n  requires due <= wallet.amount;\n  outcomes { success (Cash, Cash) };\n}\n\nfn pay(wallet : Cash, due : U64) -> (Cash, Cash) satisfies Pay {\n  let Cash { amount = total } = wallet;\n  return (construct Cash { amount = due }, construct Cash { amount = total - due });\n}\n\ncallable Smaller(a : U64, b : U64) -> U64 {\n  outcomes { success U64 };\n}\n\nfn smaller(a : U64, b : U64) -> U64 satisfies Smaller {\n  if le(a, b) {\n    return a;\n  } else {\n    return b;\n  };\n}\n\n// Curve and buyer. Each round the curve says how many tokens are left; the\n// buyer asks for some, hears the price, and pays or declines.\nprotocol Trade {\n  role Curve = recursive Round = select {\n    Open => send (left : U64) then offer {\n      Ask => receive (count : U64) then send (due : U64) then offer {\n        Accept => receive (payment : Cash) then send (tokens : Token) then continue Round |\n        Decline => continue Round\n      } |\n      Pass => continue Round\n    } |\n    Graduated => end Graduated |\n    Failed => receive (tokens : Token) then send (refund : Cash) then end Refunded\n  };\n  role Buyer = recursive Round = offer {\n    Open => receive (left : U64) then select {\n      Ask => send (count : U64) then receive (due : U64) then select {\n        Accept => send (payment : Cash) then receive (tokens : Token) then continue Round |\n        Decline => continue Round\n      } |\n      Pass => continue Round\n    } |\n    Graduated => end Graduated |\n    Failed => send (tokens : Token) then receive (refund : Cash) then end Refunded\n  };\n}\n\n// Curve and pool: on graduation the reserve and the liquidity tokens arrive together.\nprotocol Seed {\n  role Curve = select {\n    Fund => send (reserve : Cash) then send (liquidity : Token) then end Funded |\n    Cancel => end Cancelled\n  };\n  role Pool = offer {\n    Fund => receive (reserve : Cash) then receive (liquidity : Token) then end Funded |\n    Cancel => end Cancelled\n  };\n}\n\ncomponent Curve(\n  buyer : Curve[Trade],\n  pool : Curve[Seed],\n  supply : {v : U64 | v <= 1000000},\n  base : {v : U64 | v <= 1000000},\n  slope : {v : U64 | v <= 1000},\n  rounds : {v : U64 | v <= 50}\n) provides U64 {\n  loop state (b = buyer, reserve = construct Cash { amount = 0 }, sold : U64 = 0, round : U64 = 0) {\n    if eq(sold, supply) {\n      // Sold out: graduate. The pool gets the whole reserve and a matching batch of tokens.\n      let b_done = select Graduated on b;\n      close b_done;\n      let raised = borrow reserve as r { return r.amount; };\n      let p1 = select Fund on pool;\n      let p2 = send reserve on p1;\n      let p3 = send construct Token { amount = supply } on p2;\n      close p3;\n      console_write(\"graduated with a reserve of\", raised);\n      return raised;\n    } else {\n      if ge(round, rounds) {\n        // Out of time: fail. Take the tokens back and return every unit of cash.\n        let failing = select Failed on b;\n        let (b1, returned) = receive Token on failing;\n        let b2 = send refund(returned, sold, reserve) on b1;\n        close b2;\n        let p1 = select Cancel on pool;\n        close p1;\n        console_write(\"launch failed after\", round, \"rounds\");\n        return 0;\n      } else {\n        let b1 = select Open on b;\n        let b2 = send supply - sold on b1;\n        offer b2 {\n          Ask => {\n            let (b3, count) = receive U64 on b2;\n            let due = quote(sold, count, base, slope);\n            let b4 = send due on b3;\n            offer b4 {\n              Accept => {\n                let (b5, payment) = receive Cash on b4;\n                let (tokens, cash) = mint(payment, due, count);\n                let b6 = send tokens on b5;\n                continue (b6, add(reserve, cash), sold + count, round + 1);\n              }\n              Decline => {\n                continue (b4, reserve, sold, round + 1);\n              }\n            };\n          }\n          Pass => {\n            continue (b2, reserve, sold, round + 1);\n          }\n        };\n      };\n    };\n  };\n}\n\ncomponent Buyer(curve : Buyer[Trade], per_round : U64, wallet : U64) provides U64 {\n  loop state (ep = curve, cash = construct Cash { amount = wallet }, bag = construct Token { amount = 0 }) {\n    offer ep {\n      Open => {\n        let (e1, left) = receive U64 on ep;\n        let count = smaller(per_round, left);\n        if gt(count, 0) {\n          let asking = select Ask on e1;\n          let e2 = send count on asking;\n          let (e3, due) = receive U64 on e2;\n          let funds = borrow cash as c { return c.amount; };\n          if ge(funds, due) {\n            let (payment, change) = pay(cash, due);\n            let accepting = select Accept on e3;\n            let e4 = send payment on accepting;\n            let (e5, tokens) = receive Token on e4;\n            continue (e5, change, stack(bag, tokens));\n          } else {\n            let declining = select Decline on e3;\n            continue (declining, cash, bag);\n          };\n        } else {\n          let passing = select Pass on e1;\n          continue (passing, cash, bag);\n        };\n      }\n      Graduated => {\n        close ep;\n        let Token { amount = held } = bag;\n        let Cash { amount = left } = cash;\n        console_write(\"buyer holds\", held, \"tokens and\", left, \"cash\");\n        return held;\n      }\n      Failed => {\n        let e1 = send bag on ep;\n        let (done, refunded) = receive Cash on e1;\n        close done;\n        let Cash { amount = back } = add(cash, refunded);\n        console_write(\"buyer refunded, cash back to\", back);\n        return 0;\n      }\n    };\n  };\n}\n\ncomponent Pool(curve : Pool[Seed]) provides U64 {\n  offer curve {\n    Fund => {\n      let (p1, reserve) = receive Cash on curve;\n      let (done, liquidity) = receive Token on p1;\n      close done;\n      let Cash { amount = cash } = reserve;\n      let Token { amount = tokens } = liquidity;\n      console_write(\"pool opened with\", cash, \"cash and\", tokens, \"tokens\");\n      return cash;\n    }\n    Cancel => {\n      close curve;\n      return 0;\n    }\n  };\n}\n\narchitecture Launch {\n  instance curve = Curve;\n  instance buyer = Buyer;\n  instance pool = Pool;\n  process curve_run = curve;\n  process buyer_run = buyer;\n  process pool_run = pool;\n  protocol trade = Trade;\n  protocol seed = Seed;\n  role trade.Curve = curve;\n  role trade.Buyer = buyer;\n  role seed.Curve = curve;\n  role seed.Pool = pool;\n  entry supply : U64;\n  entry base : U64;\n  entry slope : U64;\n  entry rounds : U64;\n  entry per_round : U64;\n  entry wallet : U64;\n  bind curve.buyer = trade.Curve;\n  bind curve.pool = seed.Curve;\n  bind curve.supply = supply;\n  bind curve.base = base;\n  bind curve.slope = slope;\n  bind curve.rounds = rounds;\n  bind buyer.curve = trade.Buyer;\n  bind buyer.per_round = per_round;\n  bind buyer.wallet = wallet;\n  bind pool.curve = seed.Pool;\n}\n\nprogram main = instantiate Launch;\n";
